#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

template <typename scalar_t>
__global__ void fused_final_bn_relu_gap_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ running_mean,
    const scalar_t* __restrict__ running_var,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ out,
    int64_t n,
    int64_t c,
    int64_t h,
    int64_t w,
    float eps) {
    const int64_t nc = static_cast<int64_t>(blockIdx.x);
    const int64_t n_idx = nc / c;
    const int64_t c_idx = nc - n_idx * c;
    const int64_t spatial = h * w;
    const int64_t base = (n_idx * c + c_idx) * spatial;

    const float mean = static_cast<float>(running_mean[c_idx]);
    const float var = static_cast<float>(running_var[c_idx]);
    const float gamma = static_cast<float>(weight[c_idx]);
    const float beta = static_cast<float>(bias[c_idx]);
    const float scale = gamma / sqrtf(var + eps);
    const float shift = beta - mean * scale;

    float thread_sum = 0.0f;
    for (int64_t i = threadIdx.x; i < spatial; i += blockDim.x) {
        const float v = static_cast<float>(x[base + i]);
        float y = v * scale + shift;
        y = y > 0.0f ? y : 0.0f;
        thread_sum += y;
    }

    extern __shared__ float shared_sum[];
    shared_sum[threadIdx.x] = thread_sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        out[nc] = static_cast<scalar_t>(shared_sum[0] / static_cast<float>(spatial));
    }
}

